-- A widget failure must not strand this addon's trees in the host's shared GUI.
-- Returning false also prevents main from consuming stale action-button state.
function gui.render()
    local ok, result = pcall(render_settings)
    for i=#menu_stack,1,-1 do
        local node = menu_stack[i]
        local popped, why = pcall(function() node:pop() end)
        menu_stack[i] = nil
        if not popped and ok then ok, result = false, why end
    end
    if not ok then
        gui.render_error=true
        local message = tostring(result)
        if menu_error ~= message then
            console.print('[Rosie] Settings error: ' .. message)
            menu_error = message
        end
        pcall(render_menu_header, 'Rosie settings could not be displayed. See the console for details.')
        return false
    end
    gui.render_error=false
    menu_error = nil
    return result == true
end

return gui
